import { AlchemystAI } from '@alchemystai/sdk';
import * as fs from 'fs';
import * as path from 'path';

async function main() {
  const apiKey = process.env.ALCHEMYST_AI_API_KEY;
  if (!apiKey) {
    console.error('ALCHEMYST_AI_API_KEY is not set');
    process.exit(1);
  }

  const client = new AlchemystAI({ apiKey });

  const docsDir = '/home/user/docs';
  const fileNames = ['policy1.md', 'policy2.md', 'policy3.md'];

  const documents = fileNames.map((fileName) => {
    const filePath = path.join(docsDir, fileName);
    const content = fs.readFileSync(filePath, 'utf-8');
    const stats = fs.statSync(filePath);
    return {
      content,
      metadata: {
        file_name: fileName,
        group_name: ['support'],
        // Also adding camelCase versions just in case the API prefers them at document level too
        fileName: fileName,
        fileSize: stats.size,
        fileType: 'text/markdown',
        lastModified: stats.mtime.toISOString(),
        groupName: ['support'],
      },
    };
  });

  try {
    const response = await client.v1.context.add({
      documents: documents as any,
      context_type: 'resource',
      source: 'docs',
      scope: 'internal',
      metadata: {
        fileName: 'batch_upload.zip',
        fileSize: documents.reduce((acc, doc: any) => acc + doc.metadata.fileSize, 0),
        fileType: 'application/x-directory',
        lastModified: new Date().toISOString(),
        groupName: ['support'],
      },
    });

    console.log('Successfully added documents:', JSON.stringify(response, null, 2));
  } catch (error) {
    console.error('Error adding documents:', JSON.stringify(error, null, 2));
    process.exit(1);
  }
}

main();

